using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Fetch a resource by ID from the REST API.")]
    public async Task<string> GetResource(
        [Description("The unique identifier of the resource to fetch")] string id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching resource {Id}", id);
        var response = await httpClient.GetAsync($"/api/resources/{id}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool, Description("List resources with optional filtering by category.")]
    public async Task<string> ListResources(
        [Description("Category to filter by, or empty for all")] string category = "",
        [Description("Maximum number of results to return")] int limit = 10,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Listing resources: category={Category}, limit={Limit}", category, limit);
        var url = string.IsNullOrEmpty(category)
            ? $"/api/resources?limit={limit}"
            : $"/api/resources?category={Uri.EscapeDataString(category)}&limit={limit}";

        var response = await httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool(Destructive = false, ReadOnly = false),
     Description("Create a new resource with the given name and content.")]
    public async Task<string> CreateResource(
        [Description("Display name for the new resource")] string name,
        [Description("Body content of the resource")] string content,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating resource {Name}", name);
        var payload = JsonSerializer.Serialize(new { name, content });
        var response = await httpClient.PostAsync(
            "/api/resources",
            new StringContent(payload, System.Text.Encoding.UTF8, "application/json"),
            cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

var builder = Host.CreateApplicationBuilder(args);

// CRITICAL: stdio transport uses stdout for JSON-RPC, so all logs must go to stderr
builder.Logging.AddConsole(options =>
    options.LogToStandardErrorThreshold = LogLevel.Trace);

// Register HttpClient with a base address for the target API
builder.Services.AddHttpClient<ApiTools>(client =>
{
    client.BaseAddress = new Uri("https://api.example.com");
    client.DefaultRequestHeaders.Add("Accept", "application/json");
});

builder.Services.AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();   // discovers all [McpServerToolType] classes

await builder.Build().RunAsync();

